  if (['t:', 'x:', 'd:', 'm:', 't：', 'x：', 'd：', 'm：'].some(p => key.startsWith(p))) {
  tab = '';
}
if(key.includes('@')) {
	sources="";
	} else {
		sources = `@${sources}`
		}
  var tabMap = {
  	'小说':'x:',
  	'漫画':'m:',
  	'听书':'t:',
  	'短剧':'d:',
  	'':''
  	}
