            this.switchToNextLine();
        } else {
            java.longToast("\n请点击页面右上角√才能设置成功哦~");
        }
        return;
    }

    let host = hostsbk[0];
    let autoSwitch = 'true';
    let timeoutSwitch = 'true';
    let timeout = '10';
    let notifySwitch = 'false';
    try {
        const getSpanText = (spanId) => {
            const regex = new RegExp('id="' + spanId + '"\s*>\s*([^<]*?)\s*<\/span>');
            const match = body.match(regex);
            return match ? match[1].trim() : "";
        };
        host = getSpanText('serverValue') || hostsbk[0];
        autoSwitch = getSpanText('autoSwitchValue') || 'true';
        timeoutSwitch = getSpanText('timeoutSwitchValue') || 'true';
        timeout = getSpanText('timeoutValue') || '10';
        notifySwitch = getSpanText('notifySwitchValue') || 'false';
    } catch (e) {
        host = hostsbk[0];
        autoSwitch = 'true';
        timeoutSwitch = 'true';
        timeout = '10';
        notifySwitch = 'true';
    }
    const settingsText = `线路: ${host}\n失败自动切换: ${autoSwitch == 'true' ? '开启' : '关闭'}\n超时自动切换: ${timeoutSwitch == 'true' ? '开启' : '关闭'}\n超时时间: ${timeout}秒\n切换提醒弹窗: ${notifySwitch == 'true' ? '开启' : '关闭'}`;
    java.longToast("\n" + settingsText);
    this.setVariable("线路", host, false);
    this.setVariable("自动切换", autoSwitch, false);
    this.setVariable("超时自动切换", timeoutSwitch, false);
    this.setVariable("超时时间", timeout, false);
    this.setVariable("切换提醒", notifySwitch, false);
}


