var regex = /\{"url"\s*:\s*"[^"]+"\s*,\s*"mobile"\s*:\s*"\d"\s*,\s*"isk"\s*:\s*"\d"\s*,\s*"novel"\s*:\s*"\d+"\s*,\s*"chapter"\s*:\s*"\d+"\}/;
