		return _selectSourceUrl(_data.sourceSelect);
	}
	_data.sourceSelect = null;
	return _setData(_data);
}


//获取当前地址
let index = 0;
_getUrl = () => {
	if(index<3){
		index++;
		try {
			if (!_data.loaded || !_data.url) {
				//初始化
				_init();
				return _getUrl();
			}
			return _data.url;
		} catch (err) {
			//初始化
			_init();
			return _getUrl();
		}
	}else{
		java.toast("初始化失败");
		return null;
	}
}

