function getJson(url,t,upmid){
    let commentList = [];
    let r = {};
    let allReplys = [];
    if(t==1){
        allReplys  = url;
    }else{
        let data = String(java.ajax(url));
        let JsonData = JSON.parse(data || "{}");
        data = JsonData.data;
        upmid = data.upper.mid;
        if(t!==2)
        offset = data.cursor.pagination_reply.next_offset;


        if(data.root && replyPage ==1){
            data.top_replies = [];
            data.root.rcount = 0;
            pageTotal = data.page.count;
            data.top_replies.push(data.root)
        }

        r.commentTotal = data?.cursor?.all_count;
        allReplys = data.top_replies?data.top_replies.concat(data.replies):data.replies;
    }


    for(i in allReplys){
        let x = allReplys[i];
        let comment = {};

        comment.meta =  x.reply_control.time_desc+(x.reply_control.up_reply?"•UP主回复":"");

        comment.content = parseContent(x.content.message,x.content.pictures,x.content.emote,x.content.at_name_to_mid,x.content.jump_url);
        comment.username = x.member.uname;
        comment.agreenum = x.like;
        let top = x.reply_control.is_up_top?"置顶":""
        if(top)comment.top = top;
        comment.authorid = upmid;
        comment.isAuthor = x.member.mid==upmid;
        comment.readerid = x.member.mid;
        comment.icon = x.member.nameplate.image ?? "";
        comment.rate = "LV"+x.member.level_info.current_level;
        comment.replyNum = Number(x.rcount) ?? 0;
        comment.id = x.rpid;
        comment.author_agree= x.reply_control.up_like;
        if(comment.replyNum>0){
            comment.list = x.replies?getJson(x.replies,1,upmid):[];
        }
        commentList.push(comment)
    }

    if(t==1)return commentList;

    r.list = commentList;
    return r

}     

 function parseContent(content,pics,emo,atname,jump_url){
     if(emo){
         let emok = Object.keys(emo)
         let emok2 = emok.map(key => 
                   key.replace(/[.*+?^$\{}()|[\\]\\\\]/g, '\\\\$&')
         );
         emok2.forEach((x,i)=>{
             let re = new RegExp(x,'g');
            content = content.replace(re,"<img src=\\""+emo[emok[i]].url+"\\" class=\\"emote\\">")
         })
      }

      if(atname){
          let atnamek = Object.keys(atname);
          let atname2 = atnamek.map(key => 
                   key.replace(/[.*+?^$\{}()|[\\]\\\\]/g, '\\\\$&')
         );

         atname2.forEach((x,i)=>{
             let re = new RegExp("@"+x,'g');
            content = content.replace(re,"<span class=\\"atname\\" data-readerid=\\""+atname[atnamek[i]]+"\\">@"+atnamek[i]+"</span>")
         })
      }


      if(jump_url){
          let jump_urlk = Object.keys(jump_url);
          let jump_url2 = jump_urlk.map(key => 
                   key.replace(/[.*+?^$\{}()|[\\]\\\\]/g, '\\\\$&')
         );

         jump_url2.forEach((x,i)=>{
             let re = new RegExp(x,'g');
             let aid =/^\\d+$/.test(jump_url[jump_urlk[i]].click_report)?jump_url[jump_urlk[i]].click_report:jump_urlk[i];
             let type = /^\\d+$/.test(aid)?"🎥":(/^http/.test(aid)?"🔗":"🔎");
            content = content.replace(re,"<span class=\\"jump_url\\" data-aid=\\""+aid+"\\">"+type+jump_url[jump_urlk[i]].title+"</span>")
         })
      }
    let imgs = "";

    if(pics && pics.length > 0){
    pics.forEach((x, index) => {
        imgs += \`<div class="picture-item">
            <div class="loading-spinner">加载中...</div>
            <img src="$\{x.img_src}" 
                 loading="lazy"
                 class="picture"
                 onload="this.parentNode.querySelector('.loading-spinner').style.display='none'"
                 onerror="this.parentNode.querySelector('.loading-spinner').style.display='none'; this.style.display='none'"
                 alt="图片$\{index + 1}">
        </div>\`;
    });

    imgs = \`<div class="picture-grid">$\{imgs}</div>\`;
}

     return content.replace(/\\n/g,'<br>')+imgs

 }

 function createCommentHtml(JsonData){
     if(JsonData && typeof JsonData!=="string"){
    document.querySelector(".commentTotal").textContent = "共"+JsonData.commentTotal+"条评论";
    html=createHtml(JsonData.list,"comment");
    return html;
    }else{
        java.longToast("错误");
        const loader = document.createElement('div');
        loader.className = 'loading-more';
        loader.style.cssText = \`
        text-align: center;
        padding: 10px;
        color: #666;
        font-size: 14px;
    \`;
    loader.textContent = typeof JsonData==="string"?JsonData:"加载失败，点击重试"
    loader.style.color = '#f00';
    return loader.outerHTML
    }
}

function createHtml(JsonData,t,type){
    let html = "";
    for(i in JsonData){
        let x = JsonData[i];
        let replyHtml = "";

        if(x.replyNum>0){
            let openReply ="";
               openReply = \` <div class="load-more-replies" data-id="$\{x.id}" data-num="$\{x.replyNum}">
                  <i class="fa fa-angle-double-down"></i> 共$\{x.replyNum}条回复</div>\`

            replyHtml = \`<div class="replies-section">
                $\{createHtml(x.list,"reply")}
                $\{openReply}
            </div>\`
        }
        let user_badges = "";
        if(x.top){
            user_badges = \`<div class="user-badges">
                    <div class="badge primary">$\{x.top}</div>
                </div>\`
        }else if(x.icon || x.rate){
              user_badges = \`<div class="user-badges">
                    <div class="badge gold">
                          <img src="$\{x.icon}">$\{x.rate}
                    </div>
                </div>\`
        }
        let info = "";
        if(x.agreenum>=0){
            info = \`<div class="comment-info">
                        <div class="comment-meta">$\{x.meta.replace(/•$/,'')}</div>
                        <div class="comment-actions">
                            <div class="action-btn"><i class="far fa-thumbs-up"></i> $\{x.agreenum}</div>
                       </div>
                    </div>\`
        }
        let author_agree="";
        if(x.author_agree){
             author_agree =\`<div class="like" style="flex:1;text-align:right"><div class="badge" style="background:#E9F3EE;color:#6CAB8D;display:inline-block;">UP主点赞</div></div>\`
        }
        html+=\`<div class="$\{t}-item$\{type?' reply-add':''}">
                    <div class="$\{t}-header">
                         <div class="username" data-readerid="$\{x.readerid}">$\{x.username}</div>
                        $\{x.isAuthor==1?'<div class="reply-label">UP主</div>':''}
                        $\{user_badges}
                        $\{author_agree}
                    </div>
                    <div class="comment-content">$\{x.content}</div>
                    $\{info}
                    $\{replyHtml}
                </div>\`
    };
    if(t=="comment"){
        if(html==""){
            html = \`    <div style="text-align: center;
        padding: 10px;
        color: #666;
        font-size: 14px;">暂无评论</div>\`
        }
    }
    return html
}

function checkScrollBottom() {
    if (isLoading || !hasMore) return;
    const lastComment = document.querySelector('.comment-item:last-of-type');
    if (!lastComment) return;
    const windowHeight = window.innerHeight;
    const documentHeight = document.documentElement.scrollHeight;
    const scrollTop = window.scrollY || document.documentElement.scrollTop;
    if (documentHeight - (scrollTop + windowHeight) < 100) {
        loadNextPage();
    }
}


function loadNextPage(t) {
    if(t){
        if (isReplyLoading || !hasReplyMore) return;
        replyPage++;
    }else{
        if (isLoading || !hasMore) return;
        page++;
    }
    if (offset == undefined || replyPage > Math.ceil((pageTotal/20))) { 
                hasMore = false;
                const noMore = document.createElement('div');
                noMore.className = 'no-more';
                noMore.textContent = '没有更多评论了';
                noMore.style.cssText = \`
                    text-align: center;
                    padding: 10px;
                    color: #999;
                    font-size: 14px;
                \`;
                 let container2 =   t ? document.querySelector(".reply-content") : document.querySelector('.comments-container') ;
                container2?.appendChild(noMore);
                container2.scrollTop = container2.scrollHeight - container2.clientHeight;

                return;
    }


    t ? isReplyLoading = true : isLoading = true;
    const loader = document.createElement('div');
    loader.className = 'loading-more';
    loader.textContent = '加载 第'+(t?replyPage:page)+'页 中...';
    loader.style.cssText = \`
        text-align: center;
        padding: 10px;
        color: #666;
        font-size: 14px;
    \`;

    const container = t ? document.querySelector(".reply-content") : document.querySelector('.comments-container') ;
    container.appendChild(loader);
    container.scrollTop = container.scrollHeight - container.clientHeight;

    setTimeout(() => {
        fetchMoreComments(t)
            .then(() => {
                container.removeChild(loader);
                t?isReplyLoading = false: isLoading = false;

            })
            .catch(() => {
                loader.textContent = '加载失败，点击重试';
                loader.style.color = '#f00';
                loader.onclick = () => {
                    container.removeChild(loader);
                    if(t){
                        isReplyLoading = false;
                        replyPage--
                    }else{
                        isLoading = false;
                        page--;
                     }

                   t?null: loadUrl();
                };
            });
    }, 100);
}

